import java.text.Normalizer;
import java.util.Collection;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * What the customer list is narrowed down to: a name filter and a set of
 * statuses.
 *
 * <p>The repository applies this, so the grid keeps holding one page at a time.
 *
 * <p>A customer matches when it satisfies both halves:
 * <ul>
 * <li>every whitespace-separated term of {@code name} occurs in the first or
 * the last name, ignoring case and accents;</li>
 * <li>its status is one of {@code statuses}, or no status was selected at
 * all.</li>
 * </ul>
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    private static final CustomerFilter EMPTY =
            new CustomerFilter("", EnumSet.noneOf(CustomerStatus.class));

    public CustomerFilter {
        name = name == null ? "" : WHITESPACE.matcher(name.trim()).replaceAll(" ");
        statuses = statuses == null || statuses.isEmpty()
                ? Set.of()
                : Set.copyOf(statuses);
    }

    /** The filter that matches every customer. */
    public static CustomerFilter empty() {
        return EMPTY;
    }

    /** Whether this filter narrows anything down at all. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /** The name terms, normalized; empty when no name was entered. */
    public List<String> terms() {
        return name.isEmpty() ? List.of() : List.of(WHITESPACE.split(normalize(name)));
    }

    /** The selected statuses, in {@link CustomerStatus} declaration order. */
    public List<CustomerStatus> orderedStatuses() {
        return statuses.isEmpty()
                ? List.of()
                : EnumSet.copyOf(statuses).stream().toList();
    }

    /** Whether the given customer passes this filter. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        List<String> terms = terms();
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        for (String term : terms) {
            if (!firstName.contains(term) && !lastName.contains(term)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Case- and accent-insensitive form of a string, so that {@code makinen},
     * {@code MAKINEN} and {@code mäkinen} all compare equal to {@code Mäkinen}.
     */
    private static String normalize(String value) {
        String lowerCase = value.toLowerCase(Locale.ROOT);
        String decomposed = Normalizer.normalize(lowerCase, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("");
    }

    /** Convenience factory taking any collection of statuses. */
    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
        return new CustomerFilter(name,
                statuses == null ? Set.of() : Set.copyOf(statuses));
    }
}
