+
+        assertEquals(getUrl() + "/?status=ACTIVE,CLOSED", page.url());
+    }
+
+    @Test
+    void bothFiltersEndUpInTheAddressBar() {
+        typeName("vir");
+        selectStatuses("ACTIVE", "CLOSED");
+
+        assertEquals(getUrl() + "/?name=vir&status=ACTIVE,CLOSED", page.url());
+        assertEquals("Showing 10 of 500", summary());
+    }
+
+    @Test
+    void clearingTheFilterLeavesNoParameterBehind() {
+        typeName("virtanen");
+        nameFilter().getInputLocator().fill("");
+        page.waitForCondition(() -> summary().equals("Showing 500 of 500")
+                && !page.url().contains("name="));
+
+        assertEquals(getUrl() + "/", page.url());
+    }
+
+    @Test
+    void theFilterSurvivesTalkingToTheServerAgain() {
+        typeName("vir");
+        grid().findHeaderCellByText("Last name").orElseThrow().clickSort();
+        page.waitForTimeout(500);
+
+        assertEquals(getUrl() + "/?name=vir", page.url());
+        assertEquals("Showing 15 of 500", summary());
+    }
+
+    @Test
+    void filteringDoesNotFillUpTheBackButton() {
+        int before = historyLength();
+
+        typeName("vir");
+        selectStatuses("ACTIVE");
+        typeName("virtanen");
+
+        assertEquals(before, historyLength(),
+                "each filter change pushed a history entry");
+    }
+
+    @Test
+    void reloadingAFilteredPageKeepsTheFilter() {
+        typeName("vir");
+        selectStatuses("ACTIVE", "CLOSED");
+        page.reload();
+        page.waitForCondition(() -> summary().startsWith("Showing "));
+
+        assertEquals("Showing 10 of 500", summary());
+        assertEquals("vir", nameFilter().getValue());
+        assertEquals(2, statusFilter().getSelectedItemCount());
+    }
+
+    @Test
+    void openingAFilteredUrlAppliesAndShowsTheFilter() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForCondition(() -> summary().startsWith("Showing ")
+                && !summary().equals("Showing 500 of 500"));
+
+        assertEquals("vir", nameFilter().getValue());
+        List<String> selected = statusFilter().getSelectedItems();
+        assertTrue(selected.contains("ACTIVE") && selected.contains("CLOSED"),
+                "selected statuses: " + selected);
+        assertEquals(grid().getTotalRowCount() + " of 500",
+                summary().substring("Showing ".length()));
+    }
+
+    @Test
+    void sortingStillWorksWhileFiltered() {
+        typeName("a");
+
+        grid().findHeaderCellByText("Last name").orElseThrow().clickSort();
+        page.waitForTimeout(500);
+        String firstAscending = cellText(0, 1);
+
+        grid().findHeaderCellByText("Last name").orElseThrow().clickSort();
+        page.waitForTimeout(500);
+        String firstDescending = cellText(0, 1);
+
+        assertTrue(firstAscending.compareToIgnoreCase(firstDescending) < 0,
+                "sorting a filtered grid gave " + firstAscending + " and " + firstDescending);
+        assertTrue(queryLog.rowsFetched() <= 200,
+                "sorting pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    private void typeName(String text) {
+        nameFilter().getInputLocator().fill(text);
+        page.waitForCondition(() -> page.url().contains("name=" + text));
+    }
+
+    private void selectStatuses(String... statuses) {
+        statusFilter().selectItems(statuses);
+        statusFilter().close();
+        page.waitForCondition(() -> {
+            String url = page.url();
+            for (String status : statuses) {
+                if (!url.contains(status)) {
+                    return false;
+                }
+            }
+            return url.contains("status=");
+        });
+    }
+
+    private String cellText(int row, int column) {
+        return grid().findCell(row, column).orElseThrow()
+                .getCellContentLocator().textContent().trim();
+    }
+
+    private TextFieldElement nameFilter() {
+        return new TextFieldElement(page.locator("vaadin-text-field"));
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private GridElement grid() {
+        return GridElement.get(page);
+    }
+
+    private String summary() {
+        return page.locator("#filter-summary").textContent();
+    }
+
+    private int historyLength() {
+        return (int) (Integer) page.evaluate("window.history.length");
+    }
+}
