@@ -0,0 +1,94 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+/** What the backend considers a match. */
+class CustomerFilterTest {
+
+    private static final Customer ADA = customer("Ada", "Aaltonen", CustomerStatus.ACTIVE);
+    private static final Customer JARNO = customer("Jarno", "Mäkinen", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE =
+            customer("Joséphine", "Aaltonen", CustomerStatus.CLOSED);
+
+    @Test
+    void anEmptyFilterMatchesEverything() {
+        assertTrue(CustomerFilter.empty().isEmpty());
+        assertTrue(CustomerFilter.empty().matches(ADA));
+        assertTrue(CustomerFilter.empty().matches(JARNO));
+    }
+
+    @Test
+    void everyTermMustMatchOneOfTheNames() {
+        assertTrue(name("ada aal").matches(ADA));
+        assertTrue(name("aal ada").matches(ADA));
+        assertFalse(name("ada virtanen").matches(ADA));
+    }
+
+    @Test
+    void surroundingAndRepeatedWhitespaceIsNotSignificant() {
+        assertTrue(name("   ada    aal  ").matches(ADA));
+        assertEquals(name("ada aal"), name("  ada   aal "));
+        assertEquals(List.of("ada", "aal"), name(" ada  aal ").terms());
+    }
+
+    @Test
+    void caseAndAccentsAreIgnoredInBothDirections() {
+        assertTrue(name("makinen").matches(JARNO));
+        assertTrue(name("MAKINEN").matches(JARNO));
+        assertTrue(name("mäkinen").matches(JARNO));
+        assertTrue(name("MÄKINEN").matches(JARNO));
+        assertTrue(name("josephine").matches(JOSEPHINE));
+        assertTrue(name("joséphine").matches(JOSEPHINE));
+    }
+
+    @Test
+    void noSelectedStatusMeansEveryStatus() {
+        assertTrue(new CustomerFilter("", Set.of()).matches(ADA));
+        assertTrue(new CustomerFilter("", Set.of()).matches(JARNO));
+    }
+
+    @Test
+    void aSelectedStatusExcludesTheOthers() {
+        CustomerFilter active = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE));
+        assertTrue(active.matches(ADA));
+        assertFalse(active.matches(JARNO));
+
+        CustomerFilter both = new CustomerFilter("",
+                Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+        assertTrue(both.matches(ADA));
+        assertTrue(both.matches(JOSEPHINE));
+        assertFalse(both.matches(JARNO));
+    }
+
+    @Test
+    void bothHalvesMustMatch() {
+        CustomerFilter filter = new CustomerFilter("aal", Set.of(CustomerStatus.ACTIVE));
+        assertTrue(filter.matches(ADA));
+        assertFalse(filter.matches(JOSEPHINE), "matches the name, but is CLOSED");
+        assertFalse(filter.matches(JARNO));
+    }
+
+    @Test
+    void statusesComeOutInDeclarationOrder() {
+        CustomerFilter filter = new CustomerFilter("",
+                Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                filter.orderedStatuses());
+    }
+
+    private static CustomerFilter name(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    private static Customer customer(String firstName, String lastName, CustomerStatus status) {
+        return new Customer(1, firstName, lastName,
+                firstName + "." + lastName + "@example.com", "Finland", status);
+    }
+}
